import {BASELINE,GRADES,norm,gap,compare,summarize,range,validatePolicy} from './engine.js';
import {FIELDS,parseCSV,validateRows,csv,safeUrl} from './import.js';
const $=id=>document.getElementById(id),escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let rows=[],pilot=[],page=1,policy={...BASELINE},imported=false;const pageSize=10;
function toast(s){$('toast').textContent=s;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,4500);}
function download(name,content,type='text/csv;charset=utf-8'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function filters(){return {search:$('search').value.trim().toLocaleLowerCase('tr'),province:$('province').value,district:$('district').value,grade:$('grade').value,year:$('year').value,quality:$('quality').value};}
function selected(){const f=filters();return rows.filter(r=>{const n=norm(r);return (!f.search||(r.name+' '+(r.code||'')).toLocaleLowerCase('tr').includes(f.search))&&(!f.province||r.province===f.province)&&(!f.district||r.district===f.district)&&(!f.grade||r.grade===f.grade)&&(!f.year||(r.year||'unknown')===f.year)&&(!f.quality||(f.quality==='missing'?n.min===null:f.quality==='exact'?n.exact:n.min!==null&&!n.exact));});}
function populate(){for(const [id,key,label] of [['province','province','Tüm iller'],['district','district','Tüm ilçeler'],['year','year','Tüm kayıtlar']]){const values=[...new Set(rows.filter(r=>id!=='district'||!$('province').value||r.province===$('province').value).map(r=>r[key]||'unknown'))].sort((a,b)=>a.localeCompare(b,'tr'));const old=$(id).value;$(id).innerHTML=`<option value="">${label}</option>`+values.map(v=>`<option value="${escape(v)}">${v==='unknown'?'Yılı bilinmeyen':escape(v)}</option>`).join('');if(values.includes(old))$(id).value=old;}$('grade').innerHTML='<option value="">Tüm kademeler</option>'+Object.entries(GRADES).map(([k,v])=>`<option value="${k}">${v}</option>`).join('');}
function stat(label,value,note,featured=false){return `<div class="stat${featured?' featured':''}"><span class="stat-label">${label}</span><strong class="stat-value${String(value).length>9?' small':''}">${value}</strong><small>${note}</small></div>`;}
function sourceLink(r){const url=safeUrl(r.source_url);return url?`<a href="${escape(url)}" target="_blank" rel="noopener">Kaynak sayfası</a>`:'Kaynak yok';}
function render(){
 const data=selected(),s=summarize(data,policy);page=Math.min(page,Math.max(1,Math.ceil(data.length/pageSize)));const sameYear=new Set(data.map(r=>r.year||'unknown')).size<=1&&!s.unknownYear;
 $('scope').textContent=imported?`${rows.length} içe aktarılmış kayıt. Ortak veri setine yayımlanmadı; yalnızca bu oturumda kullanılır.`:`${rows.length} kaynaklı okul kaydı. Öğrenci sayılarına ait eğitim yılı belirtilmemiş; Bayburt toplamını temsil etmez.`;
 $('stats').innerHTML=stat('Seçili okul kaydı',s.records,`${s.computed} hesaplanabilir · ${s.uncomputed} bekleyen`)+stat('Hesaplanan norm ihtiyacı',range({min:s.normMin,max:s.normMax}),`${s.computed} kayıt için araştırma hesabı`,true)+stat('Kaynaklardaki öğrenci',data.reduce((n,r)=>n+(r.students??0),0).toLocaleString('tr-TR'),'Seçili kayıtların toplamı · il toplamı değil')+stat('Eğitim yılı belirsiz',s.unknownYear,'Yıl doğrulaması bekleyen kayıt');
 $('result-count').textContent=`${data.length} okul · ${sameYear?'Aynı eğitim yılı':'Dönem tutarlılığı doğrulanmadı'} · ${imported?'İçe aktarılan veri':'Kaynak anlık görüntüleri'}`;
 $('school-rows').innerHTML=data.slice((page-1)*pageSize,page*pageSize).map(r=>{const n=norm(r),g=gap(r,n);return `<tr><td><strong>${escape(r.name)}</strong><small>${escape(r.province)} / ${escape(r.district)} · ${r.year?escape(r.year):'Eğitim yılı belirsiz'}</small>${sourceLink(r)}</td><td><span class="tag">${GRADES[r.grade]||escape(r.grade)}</span></td><td><span class="num">${r.students??'—'}</span></td><td><span class="num">${range(n)}</span><small>${n.min===null?'Veri eksik':n.exact?'Araştırma hesabı':'İstisna doğrulanmalı'}</small></td><td><button class="detail-button" data-id="${escape(r.id)}" data-year="${escape(r.year||'')}">Ayrıntı</button></td></tr>`;}).join('')||'<tr><td colspan="5" class="empty">Bu filtrelere uygun okul bulunamadı.</td></tr>';
 $('pagination').innerHTML=data.length?`<span>${(page-1)*pageSize+1}–${Math.min(page*pageSize,data.length)} / ${data.length}</span><button id="prev" ${page===1?'disabled':''}>Önceki</button><button id="next" ${page*pageSize>=data.length?'disabled':''}>Sonraki</button>`:'';
 if($('prev'))$('prev').onclick=()=>{page--;render();};if($('next'))$('next').onclick=()=>{page++;render();};renderScenario(data,s);
}
function renderScenario(data,s){
 $('scenario-stats').innerHTML=stat('Araştırma norm ihtiyacı',range({min:s.normMin,max:s.normMax}),`${s.computed} hesaplanabilir kayıt`)+stat('Senaryo norm ihtiyacı',range({min:s.scenarioMin,max:s.scenarioMax}),'Seçilen eşiklerle',true)+stat('İlave / azalan norm',range({min:s.deltaMin,max:s.deltaMax}),'Senaryo − araştırma dayanağı')+stat('Hesap bekleyen okul',s.uncomputed,'Bu kayıtlar norm toplamlarına katılmaz');
 const max=Math.max(s.normMax,s.scenarioMax,1);$('comparison-bars').innerHTML=[['Araştırma dayanağı',s.normMin,s.normMax,false],['Senaryo',s.scenarioMin,s.scenarioMax,true]].map(([l,min,n,scenario])=>`<div class="bar-row"><div class="bar-label"><span>${l}</span><strong>${range({min,max:n})} norm</strong></div><div class="bar-track"><div class="bar-fill${scenario?' scenario':''}" style="width:${n/max*100}%"></div></div></div>`).join('');
 $('scenario-scope').textContent=`${s.records} seçili kayıt; ${s.uncomputed} kayıt hesap dışı. ${s.unknownYear} kaydın eğitim yılı bilinmiyor. Bu toplam bir il veya Türkiye geneli ihtiyaç tahmini değildir.`;
 const grouped=new Map();for(const r of data){const key=JSON.stringify([r.province,r.district]);if(!grouped.has(key))grouped.set(key,[]);grouped.get(key).push(r);}const provinces=[...new Set(data.map(r=>r.province))].sort((a,b)=>a.localeCompare(b,'tr'));const groups=provinces.flatMap(province=>[[`${province} · seçili kayıt toplamı`,data.filter(r=>r.province===province)],...[...grouped.values()].filter(rs=>rs[0].province===province).sort((a,b)=>a[0].district.localeCompare(b[0].district,'tr')).map(rs=>[`${province} / ${rs[0].district}`,rs])]);$('geographic-rows').innerHTML=groups.map(([label,rs])=>{const t=summarize(rs,policy);return `<tr><td>${escape(label)}</td><td>${t.records}</td><td>${t.computed} / ${t.uncomputed}</td><td>${t.computed?range({min:t.normMin,max:t.normMax}):'Bilinmiyor'}</td><td>${t.computed?range({min:t.scenarioMin,max:t.scenarioMax}):'Bilinmiyor'}</td><td>${t.computed?range({min:t.deltaMin,max:t.deltaMax}):'Bilinmiyor'}</td><td>${t.unknownYear}</td></tr>`;}).join('')||'<tr><td colspan="7">Seçili kayıt yok.</td></tr>';
 $('scenario-rows').innerHTML=data.map(r=>{const c=compare(r,policy);return `<tr><td><strong>${escape(r.name)}</strong><small>${escape(r.district)} · ${GRADES[r.grade]}</small></td><td>${range(c.current)}</td><td>${range(c.scenario)}</td><td>${range(c.delta)}</td></tr>`;}).join('')||'<tr><td colspan="4" class="empty">Seçili kayıt yok.</td></tr>';
}
function detail(r){const n=norm(r),g=gap(r,n);$('detail-body').innerHTML=`<h2>${escape(r.name)}</h2><p class="muted">${escape(r.province)} / ${escape(r.district)} · ${GRADES[r.grade]}</p><div class="detail-grid"><div><small>Kaynak öğrenci sayısı</small><strong>${r.students??'Bilinmiyor'}</strong></div><div><small>Hesaplanan norm</small><strong>${range(n)}</strong></div><div><small>Eğitim yılı</small>${escape(r.year||'Kaynakta belirtilmemiş')}</div><div><small>Açık</small>${range(g)}</div><div><small>Yatılı / pansiyonlu</small>${r.boarding===true?'Evet':r.boarding===false?'Hayır':'Bilinmiyor'}</div><div><small>İlçe merkezi istisnası</small>${r.district_fallback===true?'Doğrulandı':r.district_fallback===false?'Uygulanmıyor':'Doğrulanmadı'}</div><div><small>Kaynak tarihi</small>${escape(r.source_date||'Belirtilmemiş')}</div><div><small>Verinin görüldüğü tarih</small>${escape(r.observed_at||'Belirtilmemiş')}</div><div><small>Mevcut PDR öğretmeni</small>${r.pdr??'Bilinmiyor'}</div><div><small>Kurum kodu</small>${escape(r.code||'Doğrulanmadı')}</div></div><h3>Hesap açıklaması</h3><ul>${n.reasons.map(x=>`<li>${escape(x)}</li>`).join('')}</ul>${n.warnings.length?'<h3>Eksik bilgiler</h3><ul>'+n.warnings.map(x=>`<li>${escape(x)}</li>`).join('')+'</ul>':''}<p class="muted">${escape(r.evidence||'İçe aktarılan veri; doğrulama yapılmadı.')}</p><p class="muted">${escape(r.notes||'')}</p><p>${sourceLink(r)}</p>${r.pdr_source_url?`<p><a href="${escape(safeUrl(r.pdr_source_url))}" target="_blank" rel="noopener">PDR personel kaynağı · ${escape(r.pdr_year||'Yıl belirsiz')}</a></p>`:''}<p class="muted">Hesap güncel resmî norm onayı değildir. Sonuç araştırma modelinin kayıt üzerindeki uygulamasıdır.</p>`;$('detail').showModal();}
$('school-rows').addEventListener('click',e=>{const b=e.target.closest('[data-id]');if(b){const r=rows.find(x=>x.id===b.dataset.id&&(x.year||'')===b.dataset.year);if(r)detail(r);}});$('close-detail').onclick=()=>$('detail').close();$('detail').addEventListener('click',e=>{if(e.target===$('detail')){const rect=$('detail').getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)$('detail').close();}});
function navigate(){const key=location.hash.slice(1).split('?')[0]||'schools',valid=['schools','scenario','data','method'].includes(key)?key:'schools';document.querySelectorAll('.page').forEach(p=>p.hidden=p.id!==`page-${valid}`);document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.page===valid);if(a.dataset.page===valid)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('breadcrumb').textContent='Çalışma alanı / '+({schools:'Okul verileri',scenario:'Norm senaryoları',data:'Veri aktarımı',method:'Yöntem ve kaynaklar'}[valid]);}window.addEventListener('hashchange',navigate);navigate();
for(const id of ['search','province','district','grade','year','quality'])$(id).addEventListener(id==='search'?'input':'change',()=>{page=1;if(id==='province'){const keep=$('grade').value;populate();$('grade').value=keep;}render();});
$('clear').onclick=()=>{for(const id of ['search','province','district','grade','year','quality'])$(id).value='';page=1;populate();render();};
function readPolicy(){return validatePolicy(Object.fromEntries(['primary','other','mesem','special','step','specialStep'].map(k=>[k,Number($(k).value)])));}
$('policy-form').onsubmit=e=>{e.preventDefault();try{policy=readPolicy();$('policy-error').hidden=true;render();toast('Senaryo hesaplandı.');}catch(e){$('policy-error').textContent=e.message;$('policy-error').hidden=false;}};
$('preset').onchange=()=>{const preset=$('preset').value;if(preset==='custom')return;policy={...BASELINE};if(['250','300'].includes(preset))policy.step=Number(preset);if(preset==='150')policy.primary=150;for(const k of ['primary','other','mesem','special','step','specialStep'])$(k).value=policy[k];render();};for(const k of ['primary','other','mesem','special','step','specialStep'])$(k).oninput=()=>$('preset').value='custom';
function results(){return selected().map(r=>{const c=compare(r,policy);return {...r,baseline_min:c.current.min,baseline_max:c.current.max,scenario_min:c.scenario.min,scenario_max:c.scenario.max,delta_min:c.delta?.min??null,delta_max:c.delta?.max??null,gap_min:c.currentGap.min,gap_max:c.currentGap.max,scenario_gap_min:c.scenarioGap.min,scenario_gap_max:c.scenarioGap.max,policy:JSON.stringify(policy),legal_status:'research_baseline_current_law_unverified'};});}
function exportResults(){const out=results();download('pdr-norm-sonuclar.csv',csv(out,[...FIELDS,'baseline_min','baseline_max','scenario_min','scenario_max','delta_min','delta_max','gap_min','gap_max','scenario_gap_min','scenario_gap_max','policy','legal_status']));}
$('export').onclick=exportResults;$('export-scenario').onclick=exportResults;
$('raw-export').onclick=()=>download('pdr-norm-okul-verisi.json',JSON.stringify(rows,null,2),'application/json');
$('template').onclick=()=>download('pdr-norm-sablon.csv',csv([],FIELDS));
$('file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>20*1024*1024)throw new Error('Dosya en fazla 20 MB olabilir.');const text=await file.text(),input=file.name.toLowerCase().endsWith('.json')?JSON.parse(text):parseCSV(text),valid=validateRows(input);rows=valid;imported=true;page=1;for(const id of ['search','province','district','grade','year','quality'])$(id).value='';populate();render();$('import-status').className='success';$('import-status').textContent=`${valid.length} kayıt içe aktarıldı. Veriler otomatik olarak doğrulanmış sayılmaz. Okul verileri ekranından inceleyebilirsin.`;}catch(e){$('import-status').className='error';$('import-status').textContent=e.message+' Mevcut veri seti korunuyor.';}};
$('restore').onclick=()=>{rows=structuredClone(pilot);imported=false;page=1;for(const id of ['search','province','district','grade','year','quality'])$(id).value='';populate();render();$('import-status').className='success';$('import-status').textContent='Pilot veri seti geri yüklendi.';};
$('share').onclick=async()=>{try{policy=readPolicy();render();const url=new URL(location.href);for(const k of ['primary','other','mesem','special','step','specialStep'])url.searchParams.set(k,policy[k]);for(const k of ['province','district','grade','year','quality','search']){if(filters()[k])url.searchParams.set(k,filters()[k]);else url.searchParams.delete(k);}url.hash='scenario';await navigator.clipboard.writeText(url.href);toast(imported?'Eşikler ve filtreler kopyalandı. İçe aktardığın veri bağlantıya eklenmez; veri dosyasını ayrıca paylaş.':'Eşikler ve filtrelerle senaryo bağlantısı kopyalandı.');}catch(e){toast('Bağlantı kopyalanamadı. Tarayıcı izinlerini kontrol et.');}};
const params=new URLSearchParams(location.search);try{const p={...BASELINE};for(const k of ['primary','other','mesem','special','step','specialStep'])if(params.has(k))p[k]=Number(params.get(k));validatePolicy(p);policy=p;for(const k of ['primary','other','mesem','special','step','specialStep'])$(k).value=p[k];if(params.has('step')||params.has('primary'))$('preset').value='custom';}catch{toast('Bağlantıdaki eşikler geçersiz; araştırma dayanağı kullanıldı.');}
try{const response=await fetch('data/schools.json');if(!response.ok)throw new Error('Okul veri dosyası yüklenemedi.');const input=await response.json();validateRows(input);rows=input;pilot=structuredClone(rows);populate();for(const k of ['province','district','grade','year','quality','search'])if(params.has(k))$(k).value=params.get(k);render();}catch(e){$('load-error').textContent=e.message+' Sayfayı yenileyebilirsin.';$('load-error').hidden=false;$('scope').textContent='Veri seti yüklenemedi.';}
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=t=>{try{Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}};register({name:'read_norm_summary',title:'Norm özeti oku',description:'Ekrandaki filtrelerle seçili okulların araştırma norm ve senaryo özetini oku.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(input&&Object.keys(input).length)throw new Error('Parametre beklenmiyor.');return {...summarize(selected(),policy),policy,legal_status:'research_baseline_current_law_unverified'};}});register({name:'configure_norm_scenario',title:'Norm senaryosu kur',description:'Görünür eşikleri değiştir ve aynı okul verisi üzerinde senaryoyu yeniden hesapla.',inputSchema:{type:'object',properties:Object.fromEntries(['primary','other','mesem','special','step','specialStep'].map(k=>[k,{type:'integer',minimum:1,maximum:1000000}])),required:['primary','other','mesem','special','step','specialStep'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){const keys=['primary','other','mesem','special','step','specialStep'];if(!input||Object.keys(input).some(k=>!keys.includes(k)))throw new Error('Geçersiz alan.');const next=validatePolicy({...input});policy=next;for(const k of keys)$(k).value=next[k];$('preset').value='custom';location.hash='scenario';navigate();render();return summarize(selected(),policy);}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
